const states = $input.first().json;

function getState(id) {
  const s = states.find(e => e.entity_id === id);
  return s ? parseFloat(s.state) || 0 : 0;
}

const outletsCost = getState('sensor.shellypro4pm_outlets_energy_cost');
const lightsCost = getState('sensor.shellypro4pm_lights_energy_cost');
const doorbellCost = getState('sensor.shellypro4pm_doorbell_energy_cost');
const totalCost = (outletsCost + lightsCost + doorbellCost).toFixed(2);

const rate = getState('input_number.electricity_tariff') || 1.38;
const totalKwh = (totalCost / rate).toFixed(1);

const outletsPower = getState('sensor.shellypro4pm_outlets_power');
const lightsPower = getState('sensor.shellypro4pm_lights_power');
const livePower = Math.round(outletsPower + lightsPower);

const fridgePower = getState('sensor.shellyplugsg3_8cbfea943910_power');
const pcPower = getState('sensor.pc_shelly_plug_power');
const tvPower = getState('sensor.tv_shellyplugsg_power');
const washerPower = getState('sensor.shellyplugsg3_b08184a5b7e8_power');

const text = `⚡ *Home Energy Summary (Current Month)*\n\n` +
  `• *Total Month Cost:* ${totalCost} RON\n` +
  `• *Total Month Energy:* ${totalKwh} kWh (@ ${rate} RON/kWh)\n` +
  `• *Live Draw:* ${livePower} W (Outlets: ${Math.round(outletsPower)} W, Lights: ${Math.round(lightsPower)} W)\n\n` +
  `🔌 *Active Device Draw:*\n` +
  `• Fridge: ${fridgePower.toFixed(0)} W\n` +
  `• PC: ${pcPower.toFixed(0)} W\n` +
  `• TV: ${tvPower.toFixed(0)} W\n` +
  `• Washer: ${washerPower.toFixed(0)} W`;

return [{ json: { text, totalCost, totalKwh, livePower, rate } }];
